    "note": "(2) の確かめ。10行11列は 10＋11−1＝20 番目の列の10番目で、190＋10＝200 に合う。(1) は表の数を並べて確かめる。斜めの列は、1番目：1、2番目：2,3、3番目：4,5,6 と続き、10番目の列の最後は 55。11番目の列は 56 から始まり、5番目は 60。",
