    "note": "水の温度の上がり方は、発生した熱量に比例する。熱量は 電力×時間。電圧 V が一定のとき、電力 P＝V×I＝V²/R は、全体の抵抗 R に反比例する。だから、直列と並列の全体の抵抗の比が分かれば、電力の比が分かり、時間の比とかけ合わせると熱量の比が出る。",
